// Resource limits structure
struct rlimit rlim_info;
rlim_t soft_limit, hard_limit;
int status;

// Resource constants examples:
// RLIMIT_NOFILE (Open file descriptors)
// RLIMIT_AS (Address space / Memory usage)

// Retrieve soft (rlim_cur) and hard (rlim_max) limits
status = getrlimit(RLIMIT_NOFILE, &rlim_info);

if (status == 0) {
    soft_limit = rlim_info.rlim_cur;
    hard_limit = rlim_info.rlim_max;

    // Check if limit is unlimited
    if (hard_limit == RLIM_INFINITY) {
        // ...
    }
} else {
    // Handle error (e.g., invalid resource)
}
